import Header from '../components/Header';
import Footer from '../components/Footer';
import { useState, useContext } from 'react';
import { PreferencesContext } from '../context/indexContext';

function Preferences() {
    const { mayaMode, setMayaMode } = useContext(PreferencesContext);

    function CheckboxChange(e) {
        setMayaMode(e.target.checked);
    }

    return (
        <div className='preferences-page ${mayaMode ? "maya-mode" : ""}'>
            <Header />
            <h1>Préférences</h1>
            <label>
                <input type="checkbox" checked={mayaMode} onChange={CheckboxChange} />
                Mode zzzzzzzzzzzzzzzzzzzzzzikéo
                #mayalabeille
            </label>
            <Footer />
        </div>
    )
}

export default Preferences;
